package com.bank.risk.service;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Longest uniform rating run achievable with at most k overrides.
public class RiskRatingAnalyzer {
    private static final Logger log = Logger.getLogger(RiskRatingAnalyzer.class.getName());

    public int longestUniformRun(String ratings, int k) {
        if (ratings == null || ratings.isEmpty()) {
            return 0;
        }
        Map<Character, Integer> freq = new HashMap<>();
        int left = 0;
        int maxFreq = 0;
        int best = 0;

        for (int right = 0; right < ratings.length(); right++) {
            char c = ratings.charAt(right);
            int updated = freq.merge(c, 1, Integer::sum);
            maxFreq = Math.max(maxFreq, updated);

            // If replacements needed exceed k, shrink once from the left.
            if ((right - left + 1) - maxFreq > k) {
                char leftChar = ratings.charAt(left);
                freq.merge(leftChar, -1, Integer::sum);
                final int ls = left;
                log.fine(() -> "Window needs > " + k + " overrides; shrink left from " + ls);
                left++;
            }
            best = Math.max(best, right - left + 1);
        }
        final int result = best;
        log.info(() -> "Longest uniform rating run with k=" + k + " overrides = " + result);
        return result;
    }
}
